"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[732],{3732:function(e,i,t){t.d(i,{l:function(){return a}});let a=[{slug:"standard-visitor-visa",title:"Standard Visitor Visa",lede:"Tourism, family visits, business visits and other permitted short stays.",category:"visit",image:"https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1000&q=75",overview:"The Standard Visitor route is used for tourism, visiting family and friends, certain business activities and other permitted short-term purposes. A visitor must be a genuine visitor, must leave the UK at the end of the visit, must not use visits to live in the UK for extended periods, and must have enough funds for the trip without working or accessing public funds.",noticeBox:"Important: UKVI assesses the whole picture. Your purpose, finances, employment/business position, family circumstances, travel history and supporting evidence should tell a consistent story.",preparationSteps:["Eligibility and travel-purpose assessment","Financial and home-country-ties review","Document checklist and evidence reconciliation","Online application, submission and VAC appointment booking","Biometrics guidance and post-submission support"],eligibilityChecklist:["Genuine intention to visit for a permitted purpose and leave the UK at the end of the visit","Sufficient funds for the trip, accommodation and return journey","Evidence of circumstances and ties supporting your intention to return to Pakistan","No intention to work, claim public funds or make the UK your main home through frequent visits","Meets the general suitability requirements for UK visitors"],documentsNeeded:["Valid passport with sufficient blank pages","Bank statements (verifiable 6-month transaction history and source of funds)","Employment letter, salary slips, or business registration (FBR / SECP) where applicable","Evidence of accommodation and detailed travel itinerary","Evidence of family, economic, and property ties in Pakistan","Invitation and sponsor evidence where someone in the UK is supporting the visit","Previous travel and visa history"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 3 weeks for applications made outside the UK",validity:"Up to 6 months per visit; long-term visas permit repeated visits (2, 5, 10 years)"},{slug:"skilled-worker-visa",title:"Skilled Worker Visa",lede:"For eligible sponsored employment with a UK Home Office-approved employer.",category:"work",image:"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1000&q=75",overview:"The Skilled Worker route allows UK employers licensed by the Home Office to sponsor individuals to fill eligible jobs. The applicant must have a confirmed job offer, an issued Certificate of Sponsorship (CoS), satisfy English language requirements, and meet the relevant salary threshold (general threshold or going rate for the occupation code).",noticeBox:"Important: Ensure your job offer is with a genuinely licensed sponsor and corresponds to an eligible SOC code. Fraudulent job offers or bogus sponsorships lead to mandatory refusals and permanent bans.",preparationSteps:["Certificate of Sponsorship (CoS) and salary ledger verification","Appropriate SOC code, minimum salary, and going-rate reconciliation","English language proficiency (SELT / ECCTIS) assessment","Maintenance funds and TB medical screening audit","Complete application submission and VAC appointment scheduling"],eligibilityChecklist:["Valid Certificate of Sponsorship reference number from an approved UK sponsor","Job offer at an appropriate skill level (RQF 3 or above / graduate level)","Salary meets the UKVI minimum threshold or occupation going rate","Satisfies English language requirement at minimum CEFR Level B1","Sufficient maintenance funds (unless sponsor certifies maintenance on CoS)"],documentsNeeded:["Valid passport","Certificate of Sponsorship (CoS) reference number","Proof of English proficiency (approved SELT certificate or UK degree equivalency)","Bank statement showing maintenance funds held for 28 consecutive days (if required)","Tuberculosis (TB) test certificate from an approved IOM clinic in Pakistan","Criminal record certificate for designated occupations (education, healthcare, social work)"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 3 weeks outside the UK (Priority service available)",validity:"Up to 5 years per sponsorship; leads to Indefinite Leave to Remain (ILR)"},{slug:"student-visa",title:"Student Visa",lede:"For study at a licensed UK student sponsor, generally for applicants aged 16 or over.",category:"study",image:"https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1000&q=75",overview:"The Student route is for international students who have been offered an unconditional place on a course with a licensed student sponsor in the UK. The applicant must hold a valid Confirmation of Acceptance for Studies (CAS), demonstrate sufficient funds for tuition and living expenses, and meet English language proficiency requirements.",noticeBox:"Important: UKVI and universities conduct credibility interviews. You must know your course modules, why you chose the UK, post-study intentions, and the source of all course funds.",preparationSteps:["Confirmation of Acceptance for Studies (CAS) validation and timeline check","28-day financial maintenance calculation (tuition + London/outside London living costs)","Bank statement audit for compliance with UKVI Appendix Finance rules","Credibility interview preparation and documentation review","Visa application filing, IHS payment, and VFS biometric appointment"],eligibilityChecklist:["Unconditional course offer and valid CAS number from an approved UK university","Required English proficiency level verified by the sponsor or SELT","Required funds for remaining tuition fees plus living expenses held for 28 consecutive days","ATAS certificate if required for sensitive science or engineering subjects","Passes genuine student test / credibility assessment"],documentsNeeded:["Valid passport","CAS statement issued by the licensed UK university","Bank statements showing funds held continuously for 28 days ending within 31 days of application","Academic transcripts and degree certificates specified on the CAS","Official Tuberculosis (TB) test clearance certificate from IOM Pakistan","ATAS clearance certificate (if applicable)"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 3 weeks outside the UK (Priority options available)",validity:"Duration of course plus 2 or 4 months; eligible for Graduate Route post-study work visa"},{slug:"child-student-visa",title:"Child Student Visa",lede:"For children aged 4 to 17 studying at an independent school in the United Kingdom.",category:"study",image:"https://images.unsplash.com/photo-1580582932707-520aed937b7b?auto=format&fit=crop&w=1000&q=75",overview:"The Child Student route allows children between the ages of 4 and 17 to come to the UK to study at an independent, fee-paying school. The school must hold a licensed Child Student sponsor licence. The child must have written parental consent, suitable care arrangements in place, and sufficient funds for course fees and living costs.",noticeBox:"Important: Strict safeguarding rules apply. Full evidence of accommodation, care arrangements in the UK, and parental consent from both parents is mandatory.",preparationSteps:["CAS confirmation from licensed UK independent boarding school","Parental consent affidavits and legal guardian evidence review","Accommodation and safeguarding arrangements audit","Tuition and boarding fee payment verification","Child application filing and VFS biometrics coordination"],eligibilityChecklist:["Aged between 4 and 17 at the date of application","Unconditional place at an independent school holding a Child Student sponsor licence","Written consent from both parents (or sole legal guardian)","Suitable care and reception arrangements in the UK","Sufficient funds to cover course fees and boarding / living costs"],documentsNeeded:["Valid passport of the child applicant","CAS statement issued by the independent school","Birth certificate confirming relationship with parents","Notarized letter of consent signed by both parents","Financial evidence showing tuition and boarding fees paid or maintained","Tuberculosis (TB) test certificate from IOM Pakistan"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 3 weeks outside the UK",validity:"Up to 6 years (depending on age) or course duration"},{slug:"family-partner-spouse-visa",title:"Family Visa — Partner / Spouse",lede:"For spouses, civil partners, qualifying unmarried partners and certain fianc\xe9(e) routes.",category:"family",image:"https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1000&q=75",overview:"The Partner/Spouse route under Appendix FM allows individuals to join their British citizen, settled, or qualifying partner in the UK. Applicants must demonstrate a genuine and subsisting relationship, meet the strict Minimum Income Requirement (MIR), satisfy the English language requirement, and have adequate accommodation that is not overcrowded.",noticeBox:"Important: Financial requirement rules under Appendix FM-SE are rigid. Even a single missing payslip, omitted bank statement, or minor date discrepancy can cause an immediate refusal.",preparationSteps:["Minimum Income Requirement (MIR) strategy and Category A/B/C/D/E financial reconciliation","Evidence bundle assembly for genuine and subsisting relationship","Accommodation inspection report and land registry review","English language SELT certificate verification (CEFR Level A1)","Online application filing, IHS settlement fee, and VFS submission"],eligibilityChecklist:["Partner is a British citizen, settled in the UK (ILR/PR), or holds qualifying status","Both parties are aged 18 or over at application date","Legally recognized marriage or civil partnership, or 2+ years cohabitation","Meets the Minimum Income Requirement or cash savings threshold","Adequate accommodation available without recourse to public funds","English language proficiency at CEFR A1 (A2/B1 for extensions)"],documentsNeeded:["Valid passport of applicant and copy of partner's British passport or BRP","Marriage certificate (Nikahnama) with certified English translation and NADRA registration","6 to 12 months payslips, matching bank statements, and employer letter from UK partner","P60 / HMRC tax documents for self-employed sponsors","Tenancy agreement, Land Registry title deed, and property inspection report","Call logs, chat records, wedding photos, and travel tickets proving subsisting relationship","TB medical test clearance certificate from IOM Pakistan"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 12 weeks outside the UK (Priority service 6 weeks where available)",validity:"2 years and 9 months initial grant; leads to Indefinite Leave to Remain after 5 years"},{slug:"family-dependent-child-visa",title:"Family Visa — Dependent Child",lede:"For qualifying children joining or remaining with a parent under the Family route.",category:"family",image:"https://images.unsplash.com/photo-1511895426328-dc8714191300?auto=format&fit=crop&w=1000&q=75",overview:"This route is for dependent children under 18 joining or staying with their parent(s) settled in the UK or applying at the same time as a parent. The rules require that both parents are settled in the UK or that the sponsoring parent has sole responsibility for the child's upbringing, or there are serious and compelling family considerations.",noticeBox:"Important: When only one parent is in the UK, establishing 'sole responsibility' requires extensive legal and documentary evidence of decision-making control over education, health and day-to-day welfare.",preparationSteps:["Parental status and sole responsibility evidentiary review","Appendix FM financial maintenance and income calculation","Adequate accommodation and living condition assessment","NADRA registration, family tree, and legal custody documentation","Application lodging, IHS processing, and VFS submission"],eligibilityChecklist:["Child is under 18 years of age at the date of application","Child is not married, in a civil partnership, or living an independent life","Both parents reside in the UK, or sponsoring parent has sole responsibility","Sponsoring parent meets the financial requirement","Adequate accommodation available without recourse to public funds"],documentsNeeded:["Valid passport of the child","NADRA Child Registration Certificate (B-Form) and official Birth Certificate","Evidence of sponsoring parent's UK settled status or British citizenship","Court custody orders, guardianship deeds, or evidence of sole responsibility","Financial evidence (payslips, bank statements) from sponsoring parent","Accommodation evidence confirming room for the child","TB test certificate from IOM Pakistan"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 12 weeks for settlement routes outside the UK",validity:"Granted in line with the parent's leave; leads to British citizenship / ILR"},{slug:"private-medical-treatment-visa",title:"Private Medical Treatment Visa",lede:"Medical treatment is a permitted purpose under the Standard Visitor route.",category:"visit",image:"https://images.unsplash.com/photo-1538108149393-fbbd81895907?auto=format&fit=crop&w=1000&q=75",overview:"The Private Medical Treatment route allows individuals from Pakistan to enter the UK for private consultations, surgical procedures, or specialised medical treatment at registered clinics or NHS private facilities. Applicants must demonstrate medical arrangements have been arranged, treatment is funded, and they will leave once treatment completes.",noticeBox:"Important: You must not be using NHS public treatment. All consultations and treatment plans must be on a private, pre-arranged, fee-paying basis with verified doctors or clinics.",preparationSteps:["Medical letter verification from UK registered private consultant or medical institution","Cost estimate and financial reconciliation (fees, living, accommodation, return flight)","Originating Pakistani medical diagnosis and referral review","Visa application compilation and priority scheduling","Post-submission case management and biometric support"],eligibilityChecklist:["Genuine medical condition requiring treatment in the UK","Confirmed arrangements for private medical consultation or treatment with a UK doctor/hospital","Sufficient verifiable funds to pay for all medical costs, accommodation, and travel","Intention to leave the UK at the end of treatment or within visa validity","No danger to UK public health (communicable disease restrictions apply)"],documentsNeeded:["Valid passport","Letter from registered UK private medical specialist detailing condition, proposed treatment, cost, and duration","Medical history and reports from referring doctors/hospitals in Pakistan","Bank statements or sponsor financial guarantee covering all medical and incidental costs","Proof of accommodation and travel arrangements","Tuberculosis test certificate (if stay exceeds 6 months)"],consultancyFee:"PKR 75,000",typicalProcessing:"Usually 3 weeks outside the UK (Priority options available)",validity:"Up to 6 months (or up to 11 months for extended private treatment)"},{slug:"health-and-care-worker-visa",title:"Health and Care Worker Visa",lede:"For eligible healthcare professionals with an approved UK sponsor and qualifying job.",category:"work",image:"https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&w=1000&q=75",overview:"The Health and Care Worker route is part of the Skilled Worker route, tailored for doctors, nurses, health professionals, and adult social care workers joining the NHS, NHS suppliers, or registered adult social care providers. Eligible applicants benefit from fast-track processing, reduced visa fees, and an exemption from the Immigration Health Surcharge (IHS).",noticeBox:"Important: Care workers and senior care workers sponsored after early 2024 are subject to revised dependants rules and CQC registration requirements for sponsors.",preparationSteps:["NHS or CQC-registered sponsor CoS audit and job code review","Professional registration verification (GMC, NMC, GDC, HCPC)","English language qualification (OET / IELTS for UKVI) audit","Police clearance certificate from Pakistan verification","Priority submission and biometrics scheduling"],eligibilityChecklist:["Valid Certificate of Sponsorship with 'Health and Care Worker' flag","Job offer is with NHS, NHS tier 1 contractor, or CQC-registered provider","Meets the minimum qualifying salary threshold for healthcare workers","Certified English proficiency (SELT or recognized healthcare exam)","Overseas criminal record certificate for all countries lived in last 10 years"],documentsNeeded:["Valid passport","Certificate of Sponsorship reference number from approved healthcare employer","Proof of English proficiency (OET, IELTS UKVI or degree)","Overseas Police Clearance Certificate from Pakistan police department","TB medical clearance from approved IOM clinic in Pakistan","Professional body registration confirmation (if applicable)"],consultancyFee:"PKR 75,000",typicalProcessing:"Fast-tracked: usually within 3 weeks outside the UK",validity:"Up to 5 years; leads to Indefinite Leave to Remain (ILR); exempt from IHS"},{slug:"global-talent-visa",title:"Global Talent Visa",lede:"For leaders in academia, research, arts, culture and digital technology.",category:"work",image:"https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1000&q=75",overview:"The Global Talent visa is for talented and promising individuals in specific sectors wishing to work in the UK. It does not require a job offer from an employer. The applicant must be endorsed as a recognized leader ('exceptional talent') or an emerging leader ('exceptional promise') by an approved UK endorsing body, or hold an eligible prestigious prize.",noticeBox:"Important: Two-stage process: Stage 1 is an Endorsement application to an authorized body (e.g., Tech Nation, Royal Society, British Academy, Arts Council); Stage 2 is the Visa application to UKVI.",preparationSteps:["Stage 1 endorsing body criteria alignment (Tech, Science, Research, Arts)","Evidentiary portfolio preparation (10 pieces of evidence + letters of reference)","Endorsement application submission and caseworker review","Stage 2 UKVI visa application and biometrics coordination","Settlement path planning (3-year or 5-year accelerated ILR)"],eligibilityChecklist:["Endorsement granted by an approved endorsing body (or holds an eligible prestigious prize)","Meets the criteria for Exceptional Talent (leader) or Exceptional Promise (potential leader)","Valid endorsement reference letter issued within 3 months of visa application","General suitability requirements met"],documentsNeeded:["Valid passport","Official copy of endorsement letter from the designated competent body","Full Stage 1 evidence portfolio (recommendations, media coverage, patent/code repos)","Tuberculosis (TB) test certificate from IOM Pakistan"],consultancyFee:"PKR 75,000",typicalProcessing:"Endorsement: 4-8 weeks; Visa: usually 3 weeks",validity:"Up to 5 years per application; accelerated ILR after 3 years for leaders"}]}}]);